      "code": "async function redirect(req, res) {\n  const { rows } = await db.query(\"SELECT url FROM links WHERE id = $1\", [req.params.id]);\n  if (!rows[0]) return res.status(404).end();  // unknown id\n  res.redirect(302, rows[0].url);\n}"
